DOCTYPES=('Stock Handover','Stock Handover Item','Asset Custody','Custody Accessory','Asset Incident','Incident Action','Physical Verification','Verification Item')
REPORTS=('Procurement Receipt Trace','Purchase Receipt Status','Rejected Replacement','Stock Funding Status','Pending Material Issue','Unacknowledged Issue','Handover Discrepancy','Activity Material Usage','Donor Asset Register','Asset Custody Status','Overdue Custody','Asset Maintenance Status','Damaged Missing Assets','Physical Inventory Variance','Movement Audit')
NOTICES=('Receipt Inspection Required','Handover Acknowledgement Pending','Handover Discrepancy Review','Incident Decision Pending','Verification Approval Pending')
