def audit_runtime_configuration():
 result={'missing_doctypes':[x for x in DOCTYPES if not frappe.db.exists('DocType',x)],'missing_reports':[x for x in REPORTS if not frappe.db.exists('Report',x)],'missing_notifications':[x for x in NOTICES if not frappe.db.exists('Notification',x)],'missing_templates':[x for x in TEMPLATES if not frappe.db.exists('Email Template',x)],'missing_workspace':[] if frappe.db.exists('Workspace','Inventory and Assets') else ['Inventory and Assets']};result['passed']=not any(result.values());return result
